  CONFIRM_REVIEW: ['SERVICE_AGENT_REVIEW_CONFIRMED', 'ANALYSIS_CONTINUATION'],
  CORRECT_REVIEW: ['SERVICE_AGENT_CORRECTION_ACCEPTED', 'ANALYSIS_CONTINUATION'],
  REJECT_REVIEW: ['SERVICE_AGENT_REJECTED', 'TERMINAL_NOTIFICATION'],
  APPROVE_REQUEST: ['APPROVAL_APPROVED', 'DOWNSTREAM_ACTION'],
