    && value.schema_version === '1'
    && value.status === 'ACCEPTED'
    && /^HDRESUME-[1-9][0-9]*$/.test(value.human_resume_reference)
    && /^CASE-[0-9]{4}-[0-9]{4,}$/.test(value.case_reference)
    && ['ANALYSIS_CONTINUATION', 'DOWNSTREAM_ACTION', 'TERMINAL_NOTIFICATION'].includes(value.resume_route)
    && ['ANALYZING', 'READY_FOR_ACTION', 'REJECTED'].includes(value.current_state)
