    json: {
      response_status: 200,
      response_body_json: JSON.stringify({
        schema_version: successBody.schema_version,
        status: successBody.status,
        human_resume_reference: successBody.human_resume_reference,
        case_reference: successBody.case_reference,
        resume_route: successBody.resume_route,
