  ? { error_code: errorBody.error_code, message: errorBody.message, retryable: errorBody.retryable }
  : {
      error_code: `PRIMARY_HTTP_${responseStatus}`,
      message: 'The primary human-resume endpoint returned a non-contract error.',
      retryable: responseStatus === 408 || responseStatus === 429 || responseStatus >= 500
